def tkregister2_cmdl_outputs(params: Tkregister2Cmdl, execution: Execution) -> Tkregister2CmdlOutputs:
    """Build the Tkregister2CmdlOutputs object for this tool."""
    root_v: OutputPathType = execution.output_file(".")
    return Tkregister2CmdlOutputs(
        root=root_v,
    )

def tkregister2_cmdl_execute(params: Tkregister2Cmdl, runner: Runner | None = None) -> Tkregister2CmdlOutputs:
    """
    tkregister2_cmdl

    tkregister2 is a tool to assist in the manual tuning of the linear registration between two volumes, mainly for the purpose of interacting with the FreeSurfer anatomical stream.

    Author: FreeSurfer Developers

    URL: https://github.com/freesurfer/freesurfer

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    tkregister2_cmdl_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(TKREGISTER2_CMDL_METADATA)
    execution.params(params)
    args = tkregister2_cmdl_cargs(params, execution)
    out = tkregister2_cmdl_outputs(params, execution)
    execution.run(args)
    return out

